from intake import *
import pandas as pd,numpy as np
from scipy.stats import norm,t
dev=pd.read_csv(DATA/'development_donor_metadata.csv');dev['Age']=pd.to_numeric(dev.Age,errors='coerce')
dev=dev[(dev.Age>=18)&dev.Diagnosis.isin(['Control','IPF'])]
confirm=pd.read_csv(DATA/'confirmation_donor_demographics.csv');confirm=confirm[confirm.disease.isin(['Control','IPF'])]
bulk=pd.read_csv(DATA/'bulk_metadata_unique_provisional.csv');bulk=bulk[(bulk.Age>=18)&bulk.DiseaseStatus.isin(['Normal','IPF'])]
power={}
for label,df,dc,ac in [('development',dev,'Diagnosis','Age'),('confirmation',confirm,'disease','age'),('bulk',bulk,'DiseaseStatus','Age')]:
    d=(df[dc]=='IPF').astype(float).to_numpy();age=df[ac].to_numpy(dtype=float)
    z=np.c_[np.ones(len(df)),age];res=d-z@np.linalg.lstsq(z,d,rcond=None)[0]
    se=1/np.sqrt(res@res);crit=t.ppf(.975,len(df)-3)
    power[label]=dict(n=len(df),n_ipf=int(d.sum()),n_control=int(len(d)-d.sum()),age_range_cases=[float(age[d==1].min()),float(age[d==1].max())],age_range_controls=[float(age[d==0].min()),float(age[d==0].max())],se_disease_in_residual_sd_units=float(se),ci95_halfwidth_in_residual_sd_units=float(crit*se),approx_80pct_power_mde_sd=float((crit+norm.ppf(.8))*se),assumptions='OLS linear age, homoscedastic errors; no outcome data used. Additional covariates/missing cell types reduce precision; no guarantee for nonnormal outcomes.')
atomic(DATA/'prospective_precision.json',power)
plan=dict(schema_version='openlabs.biomed_research_plan.v1',stage='exploratory_pilot',created_at_utc=now(),research_question='Does a healthy-only lung reference systematically misattribute epithelial ECM transcripts to mesenchymal sources in independent adult IPF donor pseudobulks, and does a disease-inclusive reference improve source attribution beyond a strong constant-source baseline?',
 novelty_boundary='Reference mismatch, transcriptome-size bias, IPF epithelial ECM production and spatial pathology are published. Only disease-program-specific cross-study attribution error and its failure boundary are investigated; not a novel general deconvolution algorithm or causal mechanism.',
 independent_unit='donor',primary_outcomes=['Per-IPF-donor absolute error of predicted epithelial share of summed COL1A1/COL1A2/COL3A1 UMI counts in sampled donor pseudobulk; paired mean error reduction healthy-only vs pooled reference, reported alongside best simple and closest published baseline'],minimum_relevant_effect=0.05,threshold_units='absolute RNA-source share (five percentage points), not tissue cell proportion',
 programs={'primary_ECM':['COL1A1','COL1A2','COL3A1'],'secondary_alveolar':['AGER','SFTPA1','SFTPA2','SFTPB','SFTPC','ABCA3','NAPSA']},
 baselines=['training IPF median epithelial ECM-share constant','nonnegative least squares with healthy-only reference','nonnegative least squares with IPF-only reference','nonnegative least squares with equal-donor pooled reference','ReDeconv published model with the same three reference conditions if upstream normalization/input contract is satisfiable; otherwise mark baseline unavailable and prohibit method-superiority claim'],
 max_trials=8,model_configurations=['constant','NNLS_healthy','NNLS_IPF','NNLS_pooled','ReDeconv_healthy','ReDeconv_IPF','ReDeconv_pooled'],seed=20261021,
 split_strategy='study_held_out',group_columns=['donor_id','study_id'],split_note='All eligible GSE135893 donors development; leave-one-donor-out checks within development only. GSE136831 entire study locked for one final evaluation. No artificial third partition to pass generic pilot validator.',
 confirmatory_holdout='GSE136831 adults: 32 IPF/28 control; raw expression and outcome values unopened at freeze. Published prior findings and cell labels known.',
 eligibility={'development':'GSE135893 exact released metadata barcode intersection, original diagnosis IPF/Control, known age>=18; exclude VUHD65 age17 and THD0005 unknown age','confirmation':'GSE136831 original metadata barcodes, Control/IPF only, adult demographics from supplementary table S1; combine libraries within Subject_Identity','bulk':'GSE134692 adult age>=18 IPF/Normal, deduplicate Sample.property; choose batch1 then lexicographic sample_id before expression; exclude unresolved gender/sex conflicting subjects from sex-adjusted primary model; ALI excluded','spatial':'GSE250346 corrected2025 only; exclude four canonical-ID overlaps, restrict actual IPF/Control; published count and effect table partially exposed, so corroborative/exploratory only; no independent-lab claim'},
 sampling={'method':'deterministic SHA256(seed+original_cell_id), maximum32 cells per donor and original coarse compartment; all cells retained if fewer; preserve inclusion weights N/n for pseudobulk. This is a bounded real-data subsampling pilot, not a full-atlas estimate.','compartments':['AT1','AT2','disease_epithelial','other_epithelial','fibroblast','other_mesenchymal','endothelial','immune'],'minimum_total_ECM_counts':20,'low_count_policy':'report missing/low counts and wide intervals; do not tune count cutoff; no exclusion by observed model error','raw_counts':'Use unnormalized raw/X counts only; atlas mappings are transport, not new independent datasets. No integrated embeddings or reference transfer labels.'},
 preprocessing={'markers':'Training-only marker selection excludes both endpoint programmes, mitochondrial/ribosomal genes; rank mean CPM specificity, top50 per compartment with meanCPM>=1; fixed overlap of available gene IDs; no confirmation labels/values used.','reference':'Equal donor averages of within-compartment raw mean expression; CPM reference predicts RNA mixture weights, not tissue cell fractions; report raw-vs-CPM sensitivity without labeling raw counts absolute transcriptome sizes.','bulk':'gene-length adjustment if verified annotation length available; if not available, do not claim valid scRNA-to-totalRNA deconvolution','uncertainty':'2000 paired donor bootstraps; secondary development-reference donor bootstrap100 draws to propagate reference selection uncertainty; no per-cell significance tests'},
 leakage_controls=['Freeze before expression intake; record source metadata exposures','No hypothesis/program/threshold/normalization selection on heldout results','Atlas shared annotations are not used as independent truth; map original labels','All results and exclusions retained, no favorable metric switching'],
 stop_conditions=['Cannot reconcile original barcodes/counts','Insufficient valid donor/source counts to estimate endpoint','Reference normalization cannot support source attribution','Clinical/age confounding prevents disease-specific interpretation','Transfer or memory budget insufficient after official alternatives'],
 resource_budget={'threads':2,'memory_mib':5120,'scratch_mib':12288,'download_mib':6144,'remote_metadata_mib':384,'remote_expression_target_mib':3500,'http_concurrency':2},
 limitations=['No matched tissue cell-composition truth; capture fractions differ from tissue fractions','Study/platform and clinical cohort confounding','Age strongly differs in development; direct disease-mechanism claims prohibited','Sampling32 cells per compartment may yield insufficient ECM count precision','Closest full method may require inputs unavailable within the bounded pilot','Generic train/validation/test contract not fully applicable to frozen study-held-out attribution analysis; do not fabricate pass'],paper_candidate=False)
p=DATA/'plan_frozen_v1.json'
if p.exists():raise RuntimeError('Frozen plan already exists')
atomic(p,plan);atomic(ART/'plan_frozen_v1.json',plan)
atomic(DATA/'plan_frozen_v1.sha256.json',dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
print(json.dumps(power,indent=2))
